    sum += pairs[i][0] + pairs[i][1];

    if (i === pairs.length - 1 && sum !== Number(missingCell.textContent)) {
      missingCell.textContent = pairs[pairs.length - 1][0] * 10 + pairs[pairs.length - 1][1] + 1;
      sum++;
      break;
    }
  }
}
```
