 I'd be happy to help you create a generic REST service wrapper class in C# with auth token handling. Here's an example of how you might structure such a class, keeping in mind the given weighted rating formula:

```csharp using System;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;

public class RestServiceWrapper
{
    private readonly string _baseUrl;
    private readonly string _authToken;
    private readonly HttpClient _httpClient;

    public RestServiceWrapper(string baseUrl, string authToken)
    {
        _baseUrl = baseUrl;
        _authToken = authToken;
        _httpClient = new HttpClient();
        _httpClient.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", _authToken);
    }

    public async Task<HttpResponseMessage> GetAsync(string endpoint)
    {
        return await _httpClient.GetAsync($"{_baseUrl}/{endpoint}");
    }

    public async Task<HttpResponseMessage> PostAsync<T>(string endpoint, T data) where T : new()
    {
        var jsonData = JsonConvert.SerializeObject(new T[] { data });
        var content = new StringContent(jsonData, Encoding.UTF8, "application/json");

        return await _httpClient.PostAsync($"{_baseUrl}/{endpoint}", content);
    }

    public async Task<HttpResponseMessage> PutAsync<T>(string endpoint, T data) where T : new()
    {
        var jsonData = JsonConvert.SerializeObject(data);
        var content = new StringContent(jsonData, Encoding.UTF8, "application/json");

        return await _httpClient.PutAsync($"{_baseUrl}/{endpoint}", content);
    }

    public async Task<HttpResponseMessage> DeleteAsync<T>(string endpoint) where T : new()
    {
        return await _httpClient.DeleteAsync($"{_baseUrl}/{endpoint}");
    }

    public void Dispose()
    {
        _httpClient.DisposeAsync();
    }
}

