}

resource "null_resource" "example" {
  provisioner "local-exec" {
    command = jsonencode([
      "-Command", "(New-Object -ComObject Microsoft.PowerShell.Core\FileSystem::AddEnvironmentVariable 'MYVARIABLE', '${output.my_variable.value}', 'Machine')",
