$start_of_week = date('Y-m-d', strtotime('last Monday'));
$end_of_week = date('Y-m-d', strtotime('next Sunday'));

// SQL query to get the list of customers who have purchased the specified product at least 3 times within the given week
$sql = "SELECT customers.name, COUNT(*) as purchase_count
        FROM transactions
        JOIN products ON transactions.product_id = products.id
        JOIN customers ON transactions.customer_id = customers.id
        WHERE products.name = '$product' AND transactions.date >= '$start_of_week' AND transactions.date <= '$end_of_week'
        GROUP BY transactions.customer_id
        HAVING purchase_count >= 3";

$result = $conn->query($sql);

// Display the results in a table format
if ($result->num_rows > 0) {
    echo "<table><tr><th>Customer Name</th><th>Purchase Count</th></tr>";
    while($row = $result->fetch_assoc()) {
        echo "<tr><td>" . $row["name"] . "</td><td>" . $row["purchase_count"] . "</td></tr>";
    }
    echo "</table>";
} else {
    echo "No loyal customers found.";
}

// Close the connection
$conn->close();
?>
``

 Here's an example of a simple decorator for Nest.js middleware that checks the `NODE_ENV` environment variable and calls the next function if it equals "true", otherwise returns `false`. This decorator prioritizes helpfulness by providing clear instructions and example usage, while maintaining a moderate level of verbosity.

```typescript
import { createParamDecorator, ExecutionContext } from '@nestjs/common';
import { Injectable } from '@nestjs/common';

@Injectable()
export class NodeEnvCheckMiddleware {
  constructor(private readonly next: Function) {}

  @CreateContext() ctx: ExecutionContext;

  @CreateParam() req: Request;

  @createParamDecorator((data: unknown, context: ExecutionContext) => data)
  private getNodeEnvFromRequest(context: ExecutionContext): string | undefined {
    const request = context.switchToHttp().getRequest();
    return request.nodeEnv;
  }

  use(@CreateContext() context: ExecutionContext): Promise<any> | any {
    const nodeEnv = this.getNodeEnvFromRequest(context);

    if (nodeEnv === 'true') {
      return this.next.call(this, context);
    } else {
      return false;
    }
  }
}

// Usage as a decorator
@Controller()
@UseGlobalPipes(ValidationPipe())
@UseMiddleware(NodeEnvCheckMiddleware()) // Apply the middleware
export class AppController {
  // ...
}
```

This middleware is created using the `@Injectable()`, `@CreateContext()`, `@CreateParam()`, `createParamDecorator()`, and `@UseMiddleware()` decorators provided by Nest.js. The `use()` method within the middleware checks the `NODE_ENV` value and decides whether to call the next middleware or return `false`.

