 Here's the code you can use to create `RedisClient` class with the required functionalities:

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();
    this.client.on('error', (err) => console.error(`Error connecting to Redis: ${err}`));
  }

  isAlive() {
    return this.client.connected;
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, result) => {
        if (err) {
          return reject(err);
        }
        resolve(result);
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.set(key, value, 'EX', duration, (err, reply) => {
        if (err) {
          return reject(err);
        }
        resolve(reply);
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, result) => {
        if (err) {
          return reject(err);
        }
        resolve(result);
      });
    });
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

This code creates a `RedisClient` class with the specified methods and exports an instance of the class named `redisClient`. The class uses the Node.js `redis` package to interact with Redis server, and it logs any errors to the console using the `on('error')` event. The `isAlive`, `get`, `set`, and `del` methods are defined as promised-based functions.

