 To identify if a given sentence in Go contains a double negative, you can follow these steps:

1. Define a slice of specific negative words.
2. Tokenize the given sentence into words.
3. Iterate through each word in the tokenized sentence.
4. Check if the current word is a negative word or the word "not".
5. If the previous word was also a negative word or "not", then the sentence contains a double negative.
6. Print a message indicating that the sentence contains a double negative.

Here's an example implementation of the above steps in Go:

```go
package main

import (
	"fmt"
	"strings"
)

func main() {
	negativeWords := []string{"ain't", "isn't", "aren't", "hasn't", "haven't", "hadn't", "doesn't", "don't", "didn't", "won't", "wouldn't", "shall not", "shouldn't", "can't", "couldn't", "may not", "might not", "must not"}
	sentence := "He isn't not worried about the coronavirus situation"

	words := strings.Split(sentence, " ")
	prevWord := ""
	doubleNegative := false

	for _, word := range words {
		if contains(negativeWords, word) || word == "not" {
			if prevWord != "" && contains(negativeWords, prevWord) || prevWord == "not" {
				doubleNegative = true
				break
			}
		}
		prevWord = word
	}

	if doubleNegative {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence does not contain a double negative.")
	}
}

func contains(slice []string, item string) bool {
	for _,a := range slice {
		if a == item {
			return true
		}
	}
	return false
}
```

